  for r in csv.DictReader(open(f)):
   if r['status']=='brief_start': ev.append((dt.datetime.fromisoformat(r['timestamp']),1,r['brief_id']))
   elif r['status']=='brief_stop': ev.append((dt.datetime.fromisoformat(r['timestamp']),-1,r['brief_id']))
 # State as set to handle duplicated stop; repeated starts after stop
 ev.sort(key=lambda x:(x[0],-x[1]))
 active=set(); prev=ev[0][0]; durations={}; bad=[]
 for ts,delta,bid in ev:
  sec=(ts-prev).total_seconds(); durations[len(active)]=durations.get(len(active),0)+sec
  if len(active)!=5 and sec>0: bad.append((prev,ts,len(active),sorted(active,key=lambda x:int(x))))
  if delta==1: active.add(bid)
  else: active.discard(bid)
  prev=ts
 total=sum(durations.values())
 print('\n',tag,'total',round(total/3600,3),'durations', {k:round(v/3600,3) for k,v in sorted(durations.items())},'final',active)
 print('long bad intervals >=60s')
 for a,b,n,s in bad:
  if (b-a).total_seconds()>=60: print(a,b,round((b-a).total_seconds()/60,1),n,s)
